    duckrice: [{ zh: '北港鴨肉飯', en: 'Beigang duck rice', ja: '北港鴨肉飯' }, 'yun', { hp: 55, buff: 'atk' }, { zh: '鴨肉絲鋪白飯，淋鴨油醬汁。', en: 'Shredded duck on rice with duck fat and sauce.', ja: '細切りの鴨肉をご飯に、鴨の脂とタレ。' }],
