    beefsoup: [{ zh: '牛肉湯 · 魚腸', en: 'Beef soup · fish gut', ja: '牛肉湯・魚腸' }, 'tnn', { hp: 80, buff: 'atk' }, { zh: '滾燙的大骨湯沖熟生牛肉片；魚腸是虱目魚的腸，煎的或汆燙都香。', en: 'Boiling bone broth poured over raw sliced beef; fish gut is milkfish intestine, pan-fried or blanched.', ja: '煮えたぎるスープを生の牛肉薄切りに注ぐ。魚腸はサバヒーの腸、焼いても湯通しでも。' }],
    fishcake: [{ zh: '旗魚黑輪', en: 'Swordfish fish-cake skewers', ja: 'カジキの黒輪' }, 'khh', { hp: 35, buff: 'def' }, { zh: '高雄的旗魚漿做成的黑輪串。', en: 'Kaohsiung fish-cake skewers made from swordfish.', ja: '高雄のカジキのすり身串。' }],
    porkknuckle: [{ zh: '萬巒豬腳', en: 'Wanluan pork knuckle', ja: '萬巒の豚足' }, 'ken', { hp: 70, buff: 'poise' }, { zh: '切片的豬腳，皮油亮 Q 彈，沾蒜蓉醬。', en: 'Sliced pork knuckle, glossy amber skin, with garlic sauce.', ja: '琥珀色に光る豚足の薄切り、にんにくダレで。' }],
    wonton: [{ zh: '花蓮扁食', en: 'Hualien wontons', ja: '花蓮の扁食' }, 'hua', { hp: 40, buff: 'regen' }, { zh: '清湯裡的小餛飩，蔥花一撒。', en: 'Little wontons in clear broth with scallion.', ja: '澄んだスープの小さなワンタン。' }],
    chili: [{ zh: '剝皮辣椒', en: 'Peeled chillies', ja: '剥皮辣椒' }, 'hua', { hp: 15, buff: 'atk' }, { zh: '去皮的青辣椒醃在醬油裡，微辣回甘。', en: 'Peeled green chillies pickled in soy — mild heat, sweet finish.', ja: '皮をむいた青唐辛子の醤油漬け、ほんのり辛く甘い。' }],
    stinkytofu: [{ zh: '玉里臭豆腐', en: 'Yuli stinky tofu', ja: '玉里の臭豆腐' }, 'hua', { hp: 45, buff: 'def' }, { zh: '外酥內軟，配泡菜。', en: 'Crisp outside, soft inside, with pickled cabbage.', ja: '外はカリッと中はふわり、キャベツの漬物と。' }],
    sugarapple: [{ zh: '鳳梨釋迦', en: 'Pineapple sugar apple', ja: 'パイナップル釈迦' }, 'tai', { hp: 30, buff: 'regen' }, { zh: '台東卑南的鳳梨釋迦，綠色鱗片、香甜。', en: 'Beinan\'s pineapple sugar apple: green scales, fragrant and sweet.', ja: '卑南のパイナップル釈迦。緑のうろこ、甘い香り。' }],
    chishangbento: [{ zh: '池上便當', en: 'Chishang lunchbox', ja: '池上弁当' }, 'tai', { hp: 75, buff: 'stam' }, { zh: '木片盒裡的池上米，配滷肉、蛋、香腸、醬菜。', en: 'Chishang rice in a wooden box with braised pork, egg, sausage and pickles.', ja: '木の箱に池上米、豚の煮込み、卵、腸詰め、漬物。' }],
    cactusice: [{ zh: '仙人掌冰', en: 'Cactus ice', ja: 'サボテンかき氷' }, 'magong', { hp: 25, buff: 'stam' }, { zh: '澎湖的仙人掌果做成的紫紅色冰。', en: 'Purple-red shaved ice from Penghu\'s cactus fruit.', ja: '澎湖のサボテンの実の紫紅色の氷。' }],
    teaegg: [{ zh: '紅茶香菇茶葉蛋', en: 'Black-tea and shiitake eggs', ja: '紅茶と椎茸の茶葉蛋' }, 'sunmoon', { hp: 25, buff: 'def' }, { zh: '大鍋阿薩姆紅茶加香菇滷的蛋。', en: 'Eggs simmered in a big pot of Assam black tea with shiitake.', ja: '大鍋のアッサム紅茶と椎茸で煮た卵。' }],
