  var BUFFN = { atk: { zh: '攻擊力 +15%', en: 'Attack +15%', ja: '攻撃力 +15%' }, def: { zh: '減傷 15%', en: 'Damage taken −15%', ja: '被ダメージ −15%' }, stam: { zh: '耐力回復 +30%', en: 'Stamina recovery +30%', ja: 'スタミナ回復 +30%' }, poise: { zh: '強韌度 +30%', en: 'Poise +30%', ja: '強靭度 +30%' }, regen: { zh: '緩慢回復 HP', en: 'Slow HP regeneration', ja: 'HP がゆっくり回復' } };
  var TX = {
    zh: { eat: '品嚐', eatNow: '現在吃', take: '帶走（放進背包）', bag: '背包', bagEmpty: '背包是空的。到各地攤販買點東西吧。', got: '放進背包：{n}', ate: '好吃！{n}（HP ＋{h}，{b}）', price: '{p} 枚', poor: '代幣不夠……', sightGo: '看看', fullBag: '這道已經帶了三份了。', foodHint: '戰鬥中可以從背包拿出來吃：回復 HP 並獲得效果。' },
    en: { eat: 'Taste', eatNow: 'Eat now', take: 'Take away (into the bag)', bag: 'Bag', bagEmpty: 'Your bag is empty. Buy something at the stalls.', got: 'Into the bag: {n}', ate: 'Delicious! {n} (HP +{h}, {b})', price: '{p} coins', poor: 'Not enough coins…', sightGo: 'Look', fullBag: 'You already carry three of these.', foodHint: 'In a fight, eat from the bag: it restores HP and gives an effect.' },
    ja: { eat: '味わう', eatNow: '今食べる', take: '持ち帰る（バッグへ）', bag: 'バッグ', bagEmpty: 'バッグは空です。屋台で何か買おう。', got: 'バッグへ：{n}', ate: 'おいしい！{n}（HP ＋{h}、{b}）', price: '{p} コイン', poor: 'コインが足りない……', sightGo: '見る', fullBag: 'これはもう三つ持っている。', foodHint: '戦闘中にバッグから食べると HP 回復と効果。' } };
  function tf(k) { return (TX[LANG] || TX.zh)[k] || TX.zh[k] || k; }
  FX_ACTL.sight = function () { return tf('sightGo'); }; FX_ACTL.food = function () { return tf('eat'); };
  function sightCard(id) { var s = SIGHT[id]; if (!s) return; P.stamps['sight.' + id] = 1; save(); card('<p class="isle__kick2">' + esc(t('mapPlaces')) + '</p><h2>' + esc(lx(s[0])) + '</h2><p class="isle__pitch">' + esc(lx(s[1])) + '</p>'); AU.fx('pop'); }
  FX_ACT.sight = function (it) { sightCard(it.id); };
  function dishPrice(id) { var d = DISH[id]; return d ? Math.max(5, Math.round(d[2].hp / 10) * 5) : 10; }
  function foodCard(id) { var d = DISH[id]; if (!d) return; P.items = P.items || {}; var pr = dishPrice(id), have = P.items[id] || 0;
    var C = card('<p class="isle__kick2">' + esc(lx((typeof K_STALL !== 'undefined' && K_STALL[d[1]]) || STN[d[1]] || LN[d[1]] || { en: '', zh: '', de: '' })) + '</p><h2>' + esc(lx(d[0])) + '</h2><p class="isle__pitch">' + esc(lx(d[3])) + '</p><p class="isle__why"><b>HP ＋' + d[2].hp + '</b> · ' + esc(lx(BUFFN[d[2].buff])) + ' · ' + esc(f(tf('price'), { p: pr })) + (have ? ' · ' + esc(tf('bag')) + ' ×' + have : '') + '</p><p class="isle__pitch" style="font-size:.86em;opacity:.8">' + esc(tf('foodHint')) + '</p><div class="isle__cact"><button type="button" class="isle__btn isle__btn--go" data-eat><b>' + esc(tf('eatNow')) + '</b></button><button type="button" class="isle__btn" data-take><b>' + esc(tf('take')) + '</b></button></div>', 'isle__cin--menu');
    C.querySelector('[data-eat]').addEventListener('click', function () { if (P.coins < pr) { toast(tf('poor')); AU.fx('bad'); return; } P.coins -= pr; P.stamps['food.' + id] = 1; save(); hud(); cardClose(); eatDish(id, false); });
    C.querySelector('[data-take]').addEventListener('click', function () { if ((P.items[id] || 0) >= 3) { toast(tf('fullBag')); return; } if (P.coins < pr) { toast(tf('poor')); AU.fx('bad'); return; } P.coins -= pr; P.items[id] = (P.items[id] || 0) + 1; P.stamps['food.' + id] = 1; save(); hud(); AU.fx('coin'); toast(f(tf('got'), { n: lx(d[0]) }), 'stamp'); cardClose(); }); }
  FX_ACT.food = function (it) { foodCard(it.id); };
  var soulEat = function () {};
  /* eating: out of a fight a cheer and a lasting buff for the next fight; in a fight the HP and a timed effect (see the combat part) */
  function eatDish(id, fromBag) { var d = DISH[id]; if (!d) return; if (fromBag) { P.items[id] = Math.max(0, (P.items[id] || 0) - 1); save(); }
    if (fight && fight.soul) { soulEat(d); return; } P.buff = P.buff || {}; P.buff['dish_' + d[2].buff] = 1; save(); AU.fx('coin'); toast(f(tf('ate'), { n: lx(d[0]), h: d[2].hp, b: lx(BUFFN[d[2].buff]) }), 'stamp'); LUNA.setMode(luna, 'cheer'); setTimeout(function () { if (luna.mode === 'cheer') LUNA.setMode(luna, 'idle'); }, 1300); }



