  /* ---------- navigation in Köln: the training centre and the six sites, the people at their posts, the trains, the places ---------- */
  var _navListK = navList; navList = function () { if (!TK || TK.id !== 'koeln') return _navListK(); var T = TK.T, S = T.spots, out = [], Y = 0.12;
    function add(o, loc) { if (!loc) return; o.L = loc.L || loc; if (loc.face) o.face = loc.face; out.push(o); }
    function person(talk) { return (GS.talkers || []).filter(function (n) { return n.talk === talk; })[0]; }
    var vend = person('vendor'), stf = person('staff'), night = isNight();
    if (S.hq) add({ id: 'lead', cat: 'train', nm: nv('lead'), sub: dn('lab') }, navSpot(T, S.hq, Y));
    KTR.sites.forEach(function (s) { var d = trx(s.cat); add({ id: 'site_' + s.cat, cat: 'train', nm: d[0], sub: d[1] + ' · ' + lx(STN[s.cat]) }, navSpot(T, s.at, s.y - TK.y)); });
    add({ id: 'guard', cat: 'people', nm: nv('guard'), sub: nv('guardS') }, navSpot(T, S.kobanDoor, Y));
    if (vend) add({ id: 'vendor', cat: 'people', nm: gx('c_vendor'), sub: nv('vendorS') }, navSpot(T, S.kioskBuy || S.kiosk, Y) || navNpc(T, vend.A));
    if (stf) add({ id: 'staff', cat: 'people', nm: nv('staff'), sub: nv('staffS') }, navNpc(T, stf.A));
    if (!night && S.gsFront) add({ id: 'max', cat: 'people', nm: 'Max · Good Startup', sub: dn('gs') }, navSpot(T, S.gsFront, Y));
    if (typeof BARN !== 'undefined') BARN.list.forEach(function (n) { var k = n.max ? 'max' : n.talk; if (!k || (k === 'max' && !night)) return; add({ id: 'bar_' + k, cat: 'people', nm: gx('c_' + k), sub: 'NO AFTERLIFE' }, navNpc(T, n.A)); });
    if (S.arrive) add({ id: 'p1', cat: 'transit', nm: nv('p1'), sub: nv('L3') }, navSpot(T, S.arrive, T.TY));
    if (S.ticket) add({ id: 'ticket', cat: 'transit', nm: nv('ticket'), sub: nv('LB1') }, navSpot(T, S.ticket, Y));
    if (S.hbfFront) add({ id: 'hbf', cat: 'transit', nm: nv('hbf'), sub: nv('hbfS') }, navSpot(T, S.hbfFront, Y));
    add({ id: 'dom', cat: 'place', nm: nv('dom'), sub: nv('domS') }, navSpot(T, S.domWest, Y));
    /* (V67) the cathedral from inside: the nave under its vaults, and the Shrine of the Three Kings seen from the ambulatory behind the high altar */
    var DF = 0.55; /* (the cathedral's floor, on its plinth: DOM.fl) */ if (S.domNave) { var lN = navSpot(T, [S.domNave[0] + 6, S.domNave[1]], DF); if (lN) lN.face = [S.domNave[0] + 30, S.domNave[1]]; add({ id: 'domIn', cat: 'place', nm: nv('domIn'), sub: nv('domInS') }, lN); }
    if (S.domAmb) { var lA = navSpot(T, S.domAmb, DF); if (lA) lA.face = [41.6, 0]; add({ id: 'domAmb', cat: 'place', nm: nv('domAmb'), sub: nv('domAmbS') }, lA); }
    if (S.bridgeW) add({ id: 'bridge', cat: 'place', nm: nv('bridge'), sub: nv('bridgeS') }, navSpot(T, S.bridgeW, T.FOOT));
    if (S.brau) add({ id: 'brau', cat: 'place', nm: nv('brau'), sub: nv('brauS') }, navSpot(T, S.brau, Y));
    if (S.barDoor) add({ id: 'bar', cat: 'place', nm: nv('bar'), sub: nv('barS') }, navSpot(T, S.barDoor, Y));
    add({ id: 'koban', cat: 'place', nm: nv('koban'), sub: nv('L0') }, navSpot(T, S.kobanDoor, Y));
    return out; };
  var _navHereK = navHere; navHere = function () { if (CITYW && TK && TK.id === 'koeln' && TK.T && inTK(pos.x, pos.z) && !TKW) return true; return _navHereK(); };
  var _cityTitleK = cityTitle; cityTitle = function () { return TK && TK.id === 'koeln' ? lx(LN.koeln) : _cityTitleK(); };
  var _navLevelK = navLevel; navLevel = function (T, y) { if (TK && TK.id === 'koeln') { return (y > T.TY - 1.2 && koInHall(pos.x, pos.z)) ? nv('L3') : nv('L0'); } return _navLevelK(T, y); };
  /* (V67) arriving in the cathedral, the view swings round behind her: the nave's length before her, or the shrine over the low screen */
  var _navArriveK = navArrive; navArrive = function () { var D = NAV.dst; _navArriveK.apply(this, arguments); if (TK && TK.id === 'koeln' && D && D.face && /^dom/.test(D.id || '')) TC.yawGoal = face + Math.PI; };

/* ===== [kt_world.js] ===== */
  /* ===== ISLE part KT (Köln): the words of part f / f2 — the sights, the street food and its stalls, the buffs, the bag, the phone,
     the strays, the waypoint, the city guide; and the island's street people re-written as harmless Köln equivalents ===== */
  /* the sights of Köln: [name, description] (facts checked; figures rounded as the sources give them) */
  SIGHT = {
    kDom: [{ en: 'Cologne Cathedral · west front', zh: '科隆大教堂（Kölner Dom） · 西立面', de: 'Kölner Dom · Westfassade' }, { en: 'Begun in 1248 and completed in 1880; its twin towers rise about 157 m, and from 1880 to 1884 it was the tallest building in the world. A UNESCO World Heritage Site since 1996.', zh: '1248 年動工、1880 年完工；雙塔高約 157 公尺，1880 到 1884 年間曾是世界最高的建築。1996 年列入聯合國教科文組織世界遺產。', de: 'Begonnen 1248, vollendet 1880: Die beiden Türme ragen rund 157 m auf, von 1880 bis 1884 war der Dom das höchste Gebäude der Welt. Seit 1996 UNESCO-Welterbe.' }],
    kKreuz: [{ en: 'The Kreuzblume', zh: '十字花尖飾（Kreuzblume）', de: 'Die Kreuzblume' }, { en: 'A full-size copy of the finials that crown the two towers: almost 10 m high and 5 m wide, made of dark-grey concrete in 1991. The real ones sit some 150 m up. A favourite meeting point.', zh: '雙塔塔頂十字花尖飾的 1:1 複製品：高近 10 公尺、寬 5 公尺，1991 年以深灰色混凝土製成。真品在約 150 公尺高的塔頂。這裡是大家最愛的集合點。', de: 'Eine Nachbildung der Kreuzblumen auf den Turmspitzen in Originalgröße: fast 10 m hoch, 5 m breit, 1991 aus dunkelgrauem Beton gefertigt. Die echten thronen rund 150 m höher. Ein beliebter Treffpunkt.' }],
    kSchrein: [{ en: 'Shrine of the Three Kings', zh: '三王聖龕', de: 'Dreikönigenschrein' }, { en: 'A gilded shrine shaped like a basilica, made about 1190–1225 for the relics of the Three Kings, brought from Milan in 1164. Over two metres long and set with more than a thousand gems and pearls — the largest goldsmith\'s work of the Middle Ages.', zh: '形如巴西利卡的鍍金聖龕，約 1190 至 1225 年間打造，供奉 1164 年從米蘭迎來的三王聖髑。長逾兩公尺、鑲有一千多顆寶石與珍珠，是中世紀最大的金工作品。', de: 'Ein vergoldeter Schrein in Gestalt einer Basilika, gefertigt etwa 1190–1225 für die Gebeine der Heiligen Drei Könige, die 1164 aus Mailand kamen. Über zwei Meter lang, mit über tausend Edelsteinen und Perlen – die größte Goldschmiedearbeit des Mittelalters.' }],
    kBridge: [{ en: 'Hohenzollern Bridge', zh: '霍亨索倫橋', de: 'Hohenzollernbrücke' }, { en: 'A 409 m railway bridge under three great steel arches: opened in 1911, blown up in 1945, rebuilt. Over 1,200 trains a day — Germany\'s busiest railway bridge. Since 2008, love locks have hung on its footpath fence.', zh: '全長 409 公尺的鐵路橋，三座大鋼拱；1911 年通車，1945 年被炸毀後重建。每天 1,200 多班列車通過，是德國最繁忙的鐵路橋。2008 年起，人行道圍欄上掛滿了愛情鎖。', de: '409 m lange Eisenbahnbrücke unter drei großen Stahlbögen: 1911 eröffnet, 1945 gesprengt, wieder aufgebaut. Täglich über 1.200 Züge – die meistbefahrene Eisenbahnbrücke Deutschlands. Seit 2008 hängen Liebesschlösser am Zaun des Fußwegs.' }],
    kReiter: [{ en: 'The bridge\'s equestrian statues', zh: '橋頭騎馬像', de: 'Die Reiterstandbilder' }, { en: 'Four bronze riders guard the bridge\'s ramps, two on each bank: Prussian kings and German emperors of the house of Hohenzollern, after which the bridge is named.', zh: '四座青銅騎馬像守在橋頭坡道，兩岸各兩座：都是霍亨索倫家族的普魯士國王與德意志皇帝——這座橋就是以這個家族命名的。', de: 'Vier bronzene Reiter bewachen die Rampen der Brücke, je zwei an jedem Ufer: preußische Könige und deutsche Kaiser aus dem Haus Hohenzollern, nach dem die Brücke benannt ist.' }],
    kHbf: [{ en: 'Köln Hauptbahnhof', zh: '科隆中央車站', de: 'Köln Hauptbahnhof' }, { en: 'A station has stood here, right beside the Dom, since 1859; the great arched hall of 1894 is 255 m long and spans 64 m. About 1,200 trains and some 280,000 travellers a day.', zh: '1859 年起這裡就有車站，緊鄰大教堂；1894 年建成的拱形月台大廳長 255 公尺、跨距 64 公尺。每天約 1,200 班列車、二十八萬人次進出。', de: 'Seit 1859 steht hier, direkt neben dem Dom, ein Bahnhof; die große Bogenhalle von 1894 ist 255 m lang und 64 m weit gespannt. Täglich rund 1.200 Züge und etwa 280.000 Reisende.' }],
    kLudwig: [{ en: 'Museum Ludwig', zh: '路德維希博物館', de: 'Museum Ludwig' }, { en: 'Opened in 1986 under zinc-clad shed roofs: art from the 20th century to today — about 900 works by Picasso (the third-largest Picasso collection in the world), plenty of Pop Art and the Russian avant-garde.', zh: '1986 年啟用，鋅板鋸齒形屋頂底下是 20 世紀至今的藝術：約 900 件畢卡索作品（世界第三大畢卡索收藏）、大量普普藝術與俄國前衛藝術。', de: 'Seit 1986 unter zinkverkleideten Sheddächern: Kunst vom 20. Jahrhundert bis heute – rund 900 Werke Picassos (die drittgrößte Picasso-Sammlung der Welt), viel Pop-Art und die russische Avantgarde.' }],
    kRGM: [{ en: 'Romano-Germanic Museum · Dionysus mosaic', zh: '羅馬-日耳曼博物館 · 酒神馬賽克', de: 'Römisch-Germanisches Museum · Dionysos-Mosaik' }, { en: 'In 1941, workers digging an air-raid shelter found the Dionysus mosaic here: over 70 m², from around AD 220–230. The museum built over it in 1974 is closed for renovation; the mosaic stays in place under cover.', zh: '1941 年挖防空洞時，在這裡發現了酒神戴奧尼索斯馬賽克：70 多平方公尺，約為西元 220 至 230 年的作品。1974 年蓋在它上方的博物館目前閉館整修，馬賽克留在原地、加蓋保護。', de: 'Beim Bau eines Luftschutzbunkers kam hier 1941 das Dionysos-Mosaik zutage: über 70 m², um 220/230 n. Chr. Das 1974 darüber gebaute Museum ist zur Sanierung geschlossen; das Mosaik bleibt geschützt an Ort und Stelle.' }],
    kBoell: [{ en: 'Heinrich-Böll-Platz', zh: '海因里希·伯爾廣場', de: 'Heinrich-Böll-Platz' }, { en: 'The roof of the Philharmonie concert hall below, and part of Dani Karavan\'s artwork "Ma\'alot": granite, cast iron, rails and trees. While the orchestra plays, guards close the square — every rolling suitcase can be heard in the hall.', zh: '廣場是地底科隆愛樂廳（Philharmonie）的屋頂，也是丹尼·卡拉萬作品〈Ma\'alot〉的一部分：花崗岩、鑄鐵、鐵軌與樹。樓下演奏時，警衛會封鎖廣場——連行李箱的滾輪聲都聽得見。', de: 'Das Dach der Philharmonie darunter und Teil von Dani Karavans Kunstwerk „Ma\'alot“ aus Granit, Gusseisen, Schienen und Bäumen. Spielt unten das Orchester, sperren Wachleute ab: Jeder Rollkoffer ist im Saal zu hören.' }],
    kGSM: [{ en: 'Groß St. Martin', zh: '大聖馬丁教堂', de: 'Groß St. Martin' }, { en: 'Built 1150–1250 on Roman foundations: a trefoil choir and a crossing tower of about 75 m with four corner turrets. Badly damaged in the war, rebuilt by 1985 — one of Cologne\'s twelve great Romanesque churches.', zh: '1150 至 1250 年間建在羅馬時代的地基上：三葉草形的聖壇，約 75 公尺高的十字交叉塔，四角各有一座小塔。二戰中嚴重受損，1985 年修復完成，是科隆十二座羅馬式教堂之一。', de: 'Erbaut 1150–1250 auf römischen Fundamenten: Dreikonchenchor und rund 75 m hoher Vierungsturm mit vier Ecktürmchen. Im Krieg schwer beschädigt, bis 1985 wiederaufgebaut – eine der zwölf großen romanischen Kirchen Kölns.' }],
    kFisch: [{ en: 'The Fischmarkt houses', zh: '魚市場的彩色老屋', de: 'Die Häuser am Fischmarkt' }, { en: 'Narrow, colourful houses with pointed gables, the tower of Groß St. Martin rising behind them — Cologne\'s postcard view. Herring has been sold on this square since the Middle Ages.', zh: '一排窄窄的彩色尖山牆老屋，後方聳立著大聖馬丁教堂的塔樓——科隆的明信片風景。這座廣場從中世紀起就在賣鯡魚。', de: 'Schmale, bunte Häuser mit spitzen Giebeln, dahinter der Turm von Groß St. Martin – Kölns Postkartenmotiv. Hering wird auf diesem Platz seit dem Mittelalter verkauft.' }],
    kMusical: [{ en: 'Musical Dome', zh: '音樂劇圓頂劇院（Musical Dome）', de: 'Musical Dome' }, { en: 'Opened in October 1996 as a temporary home for musicals — and it is still here. Its roof hangs from great steel arches outside and glows blue at night, between the station and the Rhine.', zh: '1996 年 10 月開幕，原本只是臨時的音樂劇場——結果一直留到今天。屋頂懸吊在外側的大鋼拱上，入夜後亮起藍光，就在車站與萊茵河之間。', de: 'Im Oktober 1996 als Übergangsbühne für Musicals eröffnet – und immer noch da. Das Dach hängt an mächtigen Stahlbögen und leuchtet nachts blau, zwischen Bahnhof und Rhein.' }],
    kTriangle: [{ en: 'KölnTriangle', zh: '科隆三角大樓（KölnTriangle）', de: 'KölnTriangle' }, { en: 'A glass tower in Deutz, 103 m and 29 floors, finished in 2006. From the viewing platform at the top, the Dom stands at eye level across the Rhine; on a clear day you can see as far as the Siebengebirge.', zh: '道依茨的玻璃高樓，高 103 公尺、29 層，2006 年完工。從頂樓觀景台望去，萊茵河對岸的大教堂與你平視；天氣好時，還看得到七峰山（Siebengebirge）。', de: 'Ein gläserner Turm in Deutz, 103 m hoch, 29 Geschosse, 2006 fertiggestellt. Von der Aussichtsplattform ganz oben steht der Dom auf Augenhöhe; bei klarer Sicht reicht der Blick bis zum Siebengebirge.' }],
    kBoulevard: [{ en: 'Rheinboulevard · the steps', zh: '萊茵大道階梯（Rheinboulevard）', de: 'Rheinboulevard · Freitreppe' }, { en: 'A broad flight of steps down to the Rhine on the Deutz bank, opened in 2015. Cologne comes here to sit and watch the Altstadt, the Dom and the ships across the water, with the sun going down behind them.', zh: '道依茨岸邊一路通往萊茵河的寬闊階梯，2015 年啟用。科隆人愛坐在這裡，看對岸的老城、大教堂和往來的船，太陽就在它們身後落下。', de: 'Eine breite Freitreppe hinunter zum Rhein am Deutzer Ufer, 2015 eröffnet. Hier sitzt Köln und schaut auf Altstadt, Dom und Schiffe – und die Sonne geht dahinter unter.' }],
    kHohe: [{ en: 'Hohe Straße', zh: '霍厄街（Hohe Straße）', de: 'Hohe Straße' }, { en: 'About 680 m from the Dom south to the Schildergasse, on the line of Roman Cologne\'s main north–south street, the cardo maximus. Today one of the city\'s oldest and busiest shopping streets.', zh: '從大教堂往南到希爾德巷（Schildergasse）約 680 公尺，沿著羅馬時代科隆的南北主幹道（cardo maximus）。如今是城裡最古老、也最熱鬧的購物街之一。', de: 'Rund 680 m vom Dom nach Süden bis zur Schildergasse, auf der Linie der römischen Hauptstraße, des Cardo maximus. Heute eine der ältesten und belebtesten Einkaufsstraßen der Stadt.' }]
  };
  /* the street food of Köln: [name, stall, what it does in a fight, description] (eaten now, or carried in the bag) */
