  /* the weapons (right hand): the tools of the trade; numbers as the reference */
  WPN = {
    spatula: { cls: 'straight', n: { en: 'Trench Bayonet', zh: '壕溝刺刀', de: 'Grabenseitengewehr' }, d: { en: 'Straight sword. Balanced and quick, a three-hit chain. Your first blade, from the pioneer kit.', zh: '直劍。攻守平均、出招快，連段三擊。工兵裝備裡配發的第一把。', de: 'Gerades Schwert. Ausgewogen und schnell, eine Dreierkette. Deine erste Klinge, aus der Pionierausrüstung.' }, dmg: 18, reach: 2.15, spd: 1.0, st: [12, 22], stance: 10, heavy: 1.6 },
    blade: { cls: 'katana', n: { en: 'Cavalry Sabre', zh: '騎兵軍刀', de: 'Kavalleriesäbel' }, d: { en: 'Curved blade. Fast; hits build up Debond, which bursts for heavy damage. Left by Ferrum, the Rust Colossus.', zh: '刀。速度快，命中累積「剝離」：滿了會大量剝去對手的體力。鏽之巨像費魯姆留下的。', de: 'Krummklinge. Schnell; Treffer bauen „Ablösung“ auf, die mit schwerem Schaden aufbricht. Von Ferrum, dem Rostkoloss.' }, dmg: 16, reach: 2.3, spd: 1.1, st: [11, 21], stance: 8, heavy: 1.5, bleed: 34 },
    greatsword: { cls: 'great', n: { en: 'Armour-breaker', zh: '破甲大劍', de: 'Panzerbrecher' }, d: { en: 'Greatsword. Slow and heavy, breaks stances. Taken from Slump, the Unset.', zh: '大劍。慢而沉重，削韌極高。從未凝之泥「坍落」手中奪來的。', de: 'Großschwert. Langsam und schwer, bricht die Deckung. Slump, dem Ungebundenen, abgenommen.' }, dmg: 30, reach: 2.75, spd: 0.68, st: [20, 33], stance: 22, heavy: 1.6 },
    spear: { cls: 'spear', n: { en: 'Gun Rammer', zh: '砲膛推彈桿', de: 'Ansetzer' }, d: { en: 'Spear. The longest reach; it thrusts even while you guard. Left by the Weeping Fissure.', zh: '長槍。突刺距離最遠，舉盾時也能出手。哭泣的裂縫留下的。', de: 'Speer. Die größte Reichweite; sticht sogar aus der Deckung. Vom weinenden Riss zurückgelassen.' }, dmg: 15, reach: 3.1, spd: 0.95, st: [12, 22], stance: 8, heavy: 1.5, guardAtk: true },
    hammer: { cls: 'hammer', n: { en: 'Pioneer Sledgehammer', zh: '工兵大鎚', de: 'Pionier-Vorschlaghammer' }, d: { en: 'Hammer. Strikes crush stone and armour and break stances. Left by the Oil Fiend.', zh: '槌。打擊對石頭與鎧甲特別有效，削韌高。油之惡魔留下的。', de: 'Hammer. Zertrümmert Stein und Panzer, bringt aus dem Gleichgewicht. Vom Ölteufel zurückgelassen.' }, dmg: 24, reach: 2.3, spd: 0.78, st: [16, 28], stance: 20, heavy: 1.6, strike: 1.3 },
    staff: { cls: 'staff', n: { en: 'Signal Staff', zh: '信號杖', de: 'Signalstab' }, d: { en: 'Staff. Spends focus to fire signal flares (light: quick, heavy: large). Left by the Tide Warden.', zh: '法杖。消耗專注值射出信號彈（輕：快速、重：大顆）。潮汐守衛留下的。', de: 'Stab. Verbraucht Fokus für Leuchtkugeln (leicht: schnell, schwer: groß). Vom Flutwächter zurückgelassen.' }, dmg: 7, reach: 1.9, spd: 1.0, st: [10, 18], stance: 4, heavy: 1.4, cast: [6, 22, 15, 52] } };
